    buy_book = []  # list of (price, arrival_index, id, qty)
    sell_book = []  # list of (price, arrival_index, id, qty)
    order_map = {}  # id -> (side, price, arrival_index) for cancellations
    arrival_index = 0

    for order in orders:
        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, price, arr_idx = order_map[cancel_id]
                del order_map[cancel_id]
                if side == 'buy':
                    buy_book = [(p, ai, oid, q) for p, ai, oid, q in buy_book if oid != cancel_id]
                else:
                    sell_book = [(p, ai, oid, q) for p, ai, oid, q in sell_book if oid != cancel_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3 + (1 if order_type in ['limit', 'ioc'] else 0)]
            price = order[3] if order_type in ['limit', 'ioc'] else None

            if side == 'buy':
                # Match against sell_book
                while qty > 0 and sell_book:
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    best_sell = sell_book[0]
                    sell_price, sell_arr, sell_id, sell_qty = best_sell

                    if order_type == 'market' or price >= sell_price:
                        match_qty = min(qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, match_qty])
                        qty -= match_qty

                        if match_qty == sell_qty:
                            sell_book.pop(0)
                            if sell_id in order_map:
                                del order_map[sell_id]
                        else:
                            sell_book[0] = (sell_price, sell_arr, sell_id, sell_qty - match_qty)
                    else:
                        break

                if qty > 0 and order_type in ['limit', 'ioc']:
                    if order_type == 'limit':
                        buy_book.append((price, arrival_index, order_id, qty))
                        order_map[order_id] = ('buy', price, arrival_index)
            else:  # side == 'sell'
                # Match against buy_book
                while qty > 0 and buy_book:
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    best_buy = buy_book[0]
                    buy_price, buy_arr, buy_id, buy_qty = best_buy

                    if order_type == 'market' or price <= buy_price:
                        match_qty = min(qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, match_qty])
                        qty -= match_qty

                        if match_qty == buy_qty:
                            buy_book.pop(0)
                            if buy_id in order_map:
                                del order_map[buy_id]
                        else:
                            buy_book[0] = (buy_price, buy_arr, buy_id, buy_qty - match_qty)
                    else:
                        break

                if qty > 0 and order_type in ['limit', 'ioc']:
                    if order_type == 'limit':
                        sell_book.append((price, arrival_index, order_id, qty))
                        order_map[order_id] = ('sell', price, arrival_index)

            arrival_index += 1

    return trades

